using System;
using System.IO;
using System.Runtime.InteropServices;
using System.Security.Cryptography;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Authorization;
using SixLabors.ImageSharp;
using SixLabors.ImageSharp.PixelFormats;
using SixLabors.ImageSharp.Processing;

namespace ImagePipeline.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    [Authorize]
    public class ImageProcessorController : ControllerBase
    {
        private readonly IImageTransformService _transformService;
        private readonly ILogger<ImageProcessorController> _logger;

        public ImageProcessorController(IImageTransformService transformService, ILogger<ImageProcessorController> logger)
        {
            _transformService = transformService;
            _logger = logger;
        }

        [HttpPost("transform")]
        public async Task<IActionResult> TransformImage([FromBody] TransformRequest request)
        {
            if (request == null || string.IsNullOrEmpty(request.ImageId))
                return BadRequest("Invalid request");

            if (!Guid.TryParse(request.ImageId, out _))
                return BadRequest("Invalid image ID format");

            var result = await _transformService.ApplyTransformAsync(request);
            return Ok(result);
        }
    }

    public interface IImageTransformService
    {
        Task<TransformResult> ApplyTransformAsync(TransformRequest request);
    }

    public class ImageTransformService : IImageTransformService
    {
        private readonly IPixelBufferPool _bufferPool;
        private readonly IMetadataStore _metadataStore;

        public ImageTransformService(IPixelBufferPool bufferPool, IMetadataStore metadataStore)
        {
            _bufferPool = bufferPool;
            _metadataStore = metadataStore;
        }

        public async Task<TransformResult> ApplyTransformAsync(TransformRequest request)
        {
            var metadata = await _metadataStore.GetMetadataAsync(request.ImageId);
            if (metadata == null)
                throw new InvalidOperationException("Image not found");

            var pixelBuffer = _bufferPool.Rent(metadata.Width, metadata.Height, metadata.PixelFormat);
            try
            {
                await LoadPixelDataAsync(pixelBuffer, metadata);
                ApplyKernelTransform(pixelBuffer, request.KernelType, metadata);
                var outputPath = await SaveTransformedAsync(pixelBuffer, metadata);
                return new TransformResult { OutputPath = outputPath, Success = true };
            }
            finally
            {
                _bufferPool.Return(pixelBuffer);
            }
        }

        private async Task LoadPixelDataAsync(IPixelBuffer buffer, ImageMetadata metadata)
        {
            var rawBytes = await System.IO.File.ReadAllBytesAsync(
                Path.Combine("/mnt/images", metadata.StoragePath));
            buffer.LoadFrom(rawBytes);
        }

        private void ApplyKernelTransform(IPixelBuffer buffer, KernelType kernelType, ImageMetadata metadata)
        {
            var stride = ComputeStride(metadata.Width, metadata.PixelFormat);
            var span = buffer.GetWritableSpan();

            switch (kernelType)
            {
                case KernelType.Sharpen:
                    ApplySharpenKernel(span, metadata.Width, metadata.Height, stride, metadata.PixelFormat);
                    break;
                case KernelType.Blur:
                    ApplyBlurKernel(span, metadata.Width, metadata.Height, stride, metadata.PixelFormat);
                    break;
                case KernelType.EdgeDetect:
                    ApplyEdgeKernel(span, metadata.Width, metadata.Height, stride, metadata.PixelFormat);
                    break;
            }
        }

        private int ComputeStride(int width, PixelFormatType format)
        {
            int bytesPerPixel = format switch
            {
                PixelFormatType.Rgba32 => 4,
                PixelFormatType.Rgb24 => 3,
                PixelFormatType.Bgra32 => 4,
                PixelFormatType.Gray8 => 1,
                PixelFormatType.Rgba64 => 8,
                _ => 4
            };
            return width * bytesPerPixel;
        }

        private void ApplySharpenKernel(Span<byte> data, int width, int height, int stride, PixelFormatType format)
        {
            int bytesPerPixel = stride / width;
            var temp = new byte[data.Length];
            data.CopyTo(temp);

            float[] kernel = { 0, -1, 0, -1, 5, -1, 0, -1, 0 };

            for (int y = 1; y < height - 1; y++)
            {
                for (int x = 1; x < width - 1; x++)
                {
                    for (int c = 0; c < bytesPerPixel; c++)
                    {
                        float sum = 0;
                        for (int ky = -1; ky <= 1; ky++)
                        {
                            for (int kx = -1; kx <= 1; kx++)
                            {
                                int idx = (y + ky) * stride + (x + kx) * bytesPerPixel + c;
                                sum += temp[idx] * kernel[(ky + 1) * 3 + (kx + 1)];
                            }
                        }
                        int outIdx = y * stride + x * bytesPerPixel + c;
                        data[outIdx] = (byte)Math.Clamp((int)sum, 0, 255);
                    }
                }
            }
        }

