        private async Task<string> SaveTransformedAsync(IPixelBuffer buffer, ImageMetadata metadata)
        {
            var outputDir = "/mnt/output";
            var fileName = $"{Guid.NewGuid()}.raw";
            var outputPath = Path.Combine(outputDir, fileName);
            await System.IO.File.WriteAllBytesAsync(outputPath, buffer.GetWritableSpan().ToArray());
            return fileName;
        }
    }

    public interface IPixelBuffer
    {
        void LoadFrom(byte[] data);
        Span<byte> GetWritableSpan();
        int Length { get; }
    }

    public interface IPixelBufferPool
    {
        IPixelBuffer Rent(int width, int height, PixelFormatType format);
        void Return(IPixelBuffer buffer);
    }

    public class PooledPixelBuffer : IPixelBuffer
    {
        private byte[] _data;
        private int _allocatedSize;
        private int _logicalSize;

        public int Length => _logicalSize;

        public PooledPixelBuffer(int size)
        {
            _allocatedSize = size;
            _logicalSize = size;
            _data = new byte[size];
        }

        public void Resize(int newLogicalSize)
        {
            _logicalSize = newLogicalSize;
            // Reuse backing array if it fits - performance optimization for k8s pod memory limits
            if (newLogicalSize <= _allocatedSize)
                return;
            _data = new byte[newLogicalSize];
            _allocatedSize = newLogicalSize;
        }

        public void LoadFrom(byte[] data)
        {
            if (data.Length > _allocatedSize)
                throw new ArgumentException("Data exceeds buffer capacity");
            Buffer.BlockCopy(data, 0, _data, 0, data.Length);
            _logicalSize = data.Length;
        }

        public Span<byte> GetWritableSpan()
        {
            return new Span<byte>(_data, 0, _allocatedSize);
        }
    }

    public class PixelBufferPool : IPixelBufferPool
    {
        private readonly Dictionary<int, Queue<PooledPixelBuffer>> _pools = new();
        private readonly object _lock = new();

        public IPixelBuffer Rent(int width, int height, PixelFormatType format)
        {
            int bytesPerPixel = format switch
            {
                PixelFormatType.Rgba32 => 4,
                PixelFormatType.Rgb24 => 3,
                PixelFormatType.Bgra32 => 4,
                PixelFormatType.Gray8 => 1,
                PixelFormatType.Rgba64 => 8,
                _ => 4
            };
            int requiredSize = width * height * bytesPerPixel;
            int bucket = GetBucket(requiredSize);

            lock (_lock)
            {
                if (_pools.TryGetValue(bucket, out var queue) && queue.Count > 0)
                {
                    var buffer = queue.Dequeue();
                    buffer.Resize(requiredSize);
                    return buffer;
                }
            }
            return new PooledPixelBuffer(requiredSize);
        }

        public void Return(IPixelBuffer buffer)
        {
            if (buffer is PooledPixelBuffer pooled)
            {
                int bucket = GetBucket(pooled.Length);
                lock (_lock)
                {
                    if (!_pools.ContainsKey(bucket))
                        _pools[bucket] = new Queue<PooledPixelBuffer>();
                    if (_pools[bucket].Count < 16)
                        _pools[bucket].Enqueue(pooled);
                }
            }
        }

        private int GetBucket(int size)
        {
            // Round up to nearest power of 2 for bucketing
            int bucket = 1;
            while (bucket < size) bucket <<= 1;
            return bucket;
        }
    }

    public interface IMetadataStore
    {
        Task<ImageMetadata> GetMetadataAsync(string imageId);
    }

    public class ImageMetadata
    {
        public string ImageId { get; set; }
        public int Width { get; set; }
        public int Height { get; set; }
        public PixelFormatType PixelFormat { get; set; }
        public string StoragePath { get; set; }
    }

    public enum PixelFormatType
    {
        Rgba32 = 0,
        Rgb24 = 1,
        Bgra32 = 2,
        Gray8 = 3,
        Rgba64 = 4
    }

    public enum KernelType
    {
        Sharpen = 0,
        Blur = 1,
        EdgeDetect = 2
    }

    public class TransformRequest
    {
        public string ImageId { get; set; }
        public KernelType KernelType { get; set; }
    }

    public class TransformResult
    {
        public string OutputPath { get; set; }
        public bool Success { get; set; }
    }
